const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var sonoranDesert = ee.Geometry.Polygon([
    [-115.5, 33.5],
    [-112.5, 33.5],
    [-112.5, 31.5],
    [-115.5, 31.5]
  ]); // Rough bounding box for Sonoran Desert
  var startDate = '2019-01-01';
  var endDate = '2019-12-31';

  // 2. Data Acquisition - MODIS LST (MOD11A1)
  var modisCol = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterBounds(sonoranDesert)
    .filterDate(startDate, endDate);

  var colSize = modisCol.size().getInfo();
  print('2019 MODIS Images:', colSize);

  // Check for empty collection
  if (colSize === 0) {
    print('No MODIS data found, trying MYD11A1 (Aqua)...');
    modisCol = ee.ImageCollection('MODIS/061/MYD11A1')
      .filterBounds(sonoranDesert)
      .filterDate(startDate, endDate);
    colSize = modisCol.size().getInfo();
    print('2019 MYD Images:', colSize);
    if (colSize === 0) {
      print('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Convert LST to Celsius
  var lstCelsius = modisCol.map(function(image) {
    var lst = image.select('LST_Day_1km').multiply(0.02); // Convert to Kelvin
    var qc = image.select('QC_Day');
    var mask = qc.bitwiseAnd(0b11).eq(0); // Good quality pixels only
    return lst.updateMask(mask).subtract(273.15).rename('LST_C');
  });

  // Create max composite (hottest pixel across time)
  var maxLst = lstCelsius.max();

  // 4. Check valid pixels
  var pixelCount = maxLst.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sonoranDesert,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_C').getInfo();

  print('Valid pixels after QC:', pixelCount);

  if (pixelCount === 0) {
    print('<answer>C2</answer>');
    return;
  }

  // 5. Calculate maximum temperature
  var maxTemp = maxLst.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: sonoranDesert,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_C').getInfo();

  print('Maximum LST (C):', maxTemp);

  // 6. Validation & Final Answer
  if (maxTemp === null || maxTemp === undefined || maxTemp > 200 || maxTemp < -200) {
    print('<answer>C3</answer>');
  } else if (maxTemp > 75) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
